GORSELLER = {
    "b1": '<svg viewBox="0 0 680 250" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block;font-family:\'Segoe UI\',sans-serif;"><rect width="680" height="250" rx="12" fill="#F8FAFC" stroke="#E2E8F0" stroke-width="1.5"/><text x="340" y="26" font-size="13.5" font-weight="bold" fill="#0F172A" text-anchor="middle">HÜCREDEKİ ÜÇ TEMEL RNA ÇEŞİDİ, ORANLARI VE GÖREVLERİ</text><rect x="20" y="44" width="205" height="190" rx="10" fill="#EFF6FF" stroke="#2563EB" stroke-width="1.8"/><rect x="20" y="44" width="205" height="30" rx="10" fill="#2563EB"/><rect x="20" y="62" width="205" height="12" fill="#2563EB"/><text x="122.5" y="64" font-size="11.5" font-weight="bold" fill="#FFFFFF" text-anchor="middle">1. ELÇİ RNA (mRNA — ~%5)</text><text x="32" y="92" font-size="10.5" fill="#1E293B">• DNA\'daki bir genden aldığı</text><text x="32" y="110" font-size="10.5" fill="#1E293B">  kalıtsal şifreyi KODON (üçlü</text><text x="32" y="128" font-size="10.5" fill="#1E293B">  nükleotit) halinde ribozoma</text><text x="32" y="146" font-size="10.5" fill="#1E293B">  taşır.</text><text x="32" y="164" font-size="10.5" fill="#1E293B">• Düz tek zincirlidir; yapısında</text><text x="32" y="182" font-size="10.5" fill="#1E293B">  zayıf hidrojen bağı YOKTUR.</text><text x="32" y="200" font-size="10.5" fill="#1E293B">• Hücrede en az bulunan RNA\'dır;</text><text x="32" y="218" font-size="10.5" fill="#1E293B">  tekrar tekrar kullanılabilir.</text><rect x="237" y="44" width="205" height="190" rx="10" fill="#ECFDF5" stroke="#059669" stroke-width="1.8"/><rect x="237" y="44" width="205" height="30" rx="10" fill="#059669"/><rect x="237" y="62" width="205" height="12" fill="#059669"/><text x="339.5" y="64" font-size="11.5" font-weight="bold" fill="#FFFFFF" text-anchor="middle">2. TAŞIYICI RNA (tRNA — ~%15)</text><text x="249" y="92" font-size="10.5" fill="#1E293B">• Sitoplazmadaki amino asitleri</text><text x="249" y="110" font-size="10.5" fill="#1E293B">  ANTİKODON ucuyla tanıyarak</text><text x="249" y="128" font-size="10.5" fill="#1E293B">  ribozoma taşır.</text><text x="249" y="146" font-size="10.5" fill="#1E293B">• Tek zincirin katlanmasıyla</text><text x="249" y="164" font-size="10.5" fill="#1E293B">  yonca yaprağı şeklini alır.</text><text x="249" y="182" font-size="10.5" fill="#1E293B">• Katlanma bölgelerinde ZAYIF</text><text x="249" y="200" font-size="10.5" fill="#1E293B">  HİDROJEN BAĞI bulunur.</text><text x="249" y="218" font-size="10.5" fill="#1E293B">• Tekrar tekrar kullanılabilir.</text><rect x="455" y="44" width="205" height="190" rx="10" fill="#F5F3FF" stroke="#7C3AED" stroke-width="1.8"/><rect x="455" y="44" width="205" height="30" rx="10" fill="#7C3AED"/><rect x="455" y="62" width="205" height="12" fill="#7C3AED"/><text x="557.5" y="64" font-size="11.5" font-weight="bold" fill="#FFFFFF" text-anchor="middle">3. RİBOZOMAL RNA (rRNA — ~%80)</text><text x="467" y="92" font-size="10.5" fill="#1E293B">• Ökaryotlarda çekirdekçikte</text><text x="467" y="110" font-size="10.5" fill="#1E293B">  sentezlenir; proteinlerle</text><text x="467" y="128" font-size="10.5" fill="#1E293B">  birleşip ribozomu oluşturur.</text><text x="467" y="146" font-size="10.5" fill="#1E293B">• Amino asitler arasında peptit</text><text x="467" y="164" font-size="10.5" fill="#1E293B">  bağı kurulmasında enzim gibi</text><text x="467" y="182" font-size="10.5" fill="#1E293B">  görev yapar.</text><text x="467" y="200" font-size="10.5" fill="#1E293B">• Zayıf hidrojen bağı içerir;</text><text x="467" y="218" font-size="10.5" fill="#1E293B">  en fazla bulunan RNA\'dır.</text></svg>',
    "b2": '<svg viewBox="0 0 680 250" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block;font-family:\'Segoe UI\',sans-serif;"><rect width="680" height="250" rx="12" fill="#F8FAFC" stroke="#E2E8F0" stroke-width="1.5"/><text x="340" y="26" font-size="13.5" font-weight="bold" fill="#0F172A" text-anchor="middle">DNA VE RNA MOLEKÜLLERİNİN YAPI VE İŞLEV KARŞILAŞTIRMASI</text><rect x="20" y="44" width="310" height="190" rx="10" fill="#EFF6FF" stroke="#2563EB" stroke-width="1.8"/><rect x="20" y="44" width="310" height="30" rx="10" fill="#2563EB"/><rect x="20" y="62" width="310" height="12" fill="#2563EB"/><text x="175.0" y="64" font-size="11.5" font-weight="bold" fill="#FFFFFF" text-anchor="middle">DNA\'YA ÖZGÜ ÖZELLİKLER</text><text x="32" y="92" font-size="10.5" fill="#1E293B">• Çift polinükleotit zincirlidir (sarmal).</text><text x="32" y="110" font-size="10.5" fill="#1E293B">• Kendine özgü pirimidin bazı: TİMİN (T).</text><text x="32" y="128" font-size="10.5" fill="#1E293B">• Beş karbonlu pentoz şekeri: DEOKSİRİBOZ.</text><text x="32" y="146" font-size="10.5" fill="#1E293B">• Bölünme öncesinde kendini yarı korunumlu</text><text x="32" y="164" font-size="10.5" fill="#1E293B">  olarak eşler (Enzim: DNA polimeraz).</text><text x="32" y="182" font-size="10.5" fill="#1E293B">• A = T ve G = C eşitliği zorunludur.</text><text x="32" y="200" font-size="10.5" fill="#1E293B">• Hücreyi yönetir ve kalıtımı sağlar.</text><rect x="350" y="44" width="310" height="190" rx="10" fill="#F5F3FF" stroke="#7C3AED" stroke-width="1.8"/><rect x="350" y="44" width="310" height="30" rx="10" fill="#7C3AED"/><rect x="350" y="62" width="310" height="12" fill="#7C3AED"/><text x="505.0" y="64" font-size="11.5" font-weight="bold" fill="#FFFFFF" text-anchor="middle">RNA\'YA ÖZGÜ ÖZELLİKLER</text><text x="362" y="92" font-size="10.5" fill="#1E293B">• Tek polinükleotit zincirlidir.</text><text x="362" y="110" font-size="10.5" fill="#1E293B">• Kendine özgü pirimidin bazı: URASİL (U).</text><text x="362" y="128" font-size="10.5" fill="#1E293B">• Beş karbonlu pentoz şekeri: RİBOZ.</text><text x="362" y="146" font-size="10.5" fill="#1E293B">• Kendini eşleyemez; DNA kalıbı üzerinden</text><text x="362" y="164" font-size="10.5" fill="#1E293B">  transkripsiyonla üretilir (RNA polimeraz).</text><text x="362" y="182" font-size="10.5" fill="#1E293B">• A = U veya G = C eşitliği zorunlu değildir.</text><text x="362" y="200" font-size="10.5" fill="#1E293B">• Protein sentezini doğrudan yürütür.</text></svg>',
    "b3": '<svg viewBox="0 0 680 250" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block;font-family:\'Segoe UI\',sans-serif;"><rect width="680" height="250" rx="12" fill="#F8FAFC" stroke="#E2E8F0" stroke-width="1.5"/><text x="340" y="26" font-size="13.5" font-weight="bold" fill="#0F172A" text-anchor="middle">DNA VE RNA\'DA ORTAK OLAN BİLEŞENLER VE BULUNDUKLARI HÜCRESEL KISIMLAR</text><rect x="25" y="44" width="630" height="40" rx="8" fill="#EFF6FF" stroke="#2563EB" stroke-width="1.5"/><text x="40" y="60" font-size="11" font-weight="bold" fill="#2563EB">ORTAK KİMYASAL BİLEŞENLER</text><text x="40" y="76" font-size="10.5" fill="#1E293B">Adenin (A), Guanin (G) ve Sitozin (C) organik bazları ile inorganik fosforik asit (H3PO4) grubu her ikisinde de ortaktır.</text><rect x="25" y="92" width="630" height="40" rx="8" fill="#ECFDF5" stroke="#059669" stroke-width="1.5"/><text x="40" y="108" font-size="11" font-weight="bold" fill="#059669">ORTAK KİMYASAL BAĞLAR</text><text x="40" y="124" font-size="10.5" fill="#1E293B">Nükleotit içindeki glikozit ve fosfoester bağları ile zincir boyunca uzanan fosfodiester bağları DNA ve tüm RNA\'larda ortaktır.</text><rect x="25" y="140" width="630" height="40" rx="8" fill="#FEF3C7" stroke="#D97706" stroke-width="1.5"/><text x="40" y="156" font-size="11" font-weight="bold" fill="#D97706">PROKARYOT HÜCREDE BULUNDUKLARI YER</text><text x="40" y="172" font-size="10.5" fill="#1E293B">Prokaryotlarda (bakteri ve arkeler) DNA sitoplazmada; RNA ise sitoplazma ve ribozom organelinde bulunur.</text><rect x="25" y="188" width="630" height="40" rx="8" fill="#F5F3FF" stroke="#7C3AED" stroke-width="1.5"/><text x="40" y="204" font-size="11" font-weight="bold" fill="#7C3AED">ÖKARYOT HÜCREDE BULUNDUKLARI YER</text><text x="40" y="220" font-size="10.5" fill="#1E293B">Ökaryotlarda DNA çekirdek, mitokondri ve kloroplastta; RNA ise çekirdek, çekirdekçik, sitoplazma, ribozom, mitokondri ve kloroplastta bulunur.</text></svg>',
}


def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        k = f'b{i+1}'
        if k in GORSELLER:
            b['gorsel'] = GORSELLER[k]
